mapper.select:
SELECT LICENSE_ID AS LICENSE_ID, PRODUCT_NAME AS PRODUCT_NAME, VENDOR_NAME AS VENDOR_NAME,
       LICENSE_MODEL_CD AS LICENSE_MODEL_CD, QTY AS QTY
  FROM TB_IF_LICENSE_PILOT WHERE LICENSE_ID = #{licenseId}

SELECT ASSET_ID AS ASSET_ID, LICENSE_ID AS LICENSE_ID, ALLOCATED_QTY AS ALLOCATED_QTY
  FROM TB_IF_ASSET_LICENSE_PILOT WHERE LICENSE_ID = #{licenseId}
 ORDER BY ASSET_ID
